/// A bundled prompt file the binary embeds at build time: the project it
/// belongs to, the name it is addressed by, its path within the collection,
/// the SHA-256 of [content], and the content itself.
///
/// Generated by `tool/gen_bundled_skills.dart` and `tool/gen_prompts.dart`
/// from `assets/prompts/projects/<project>/`; the app is the source of truth
/// for the presets, and the library reads from the embedded const, not from
/// disk or the asset bundle. Each entry is tagged with the project it belongs
/// to — `default` is the base set every project inherits, another project's
/// entries override a same-named default one for that project alone.
class BundledPromptFile {
  const BundledPromptFile(
      this.project, this.name, this.relativePath, this.sha256, this.content);
  final String project;
  final String name;
  final String relativePath;
  final String sha256;
  final String content;
}

/// The entry of [files] tagged [name] for [project], `default`'s standing in
/// where the project ships none of its own — the inheritance rule the
/// generators tag their lists for. Null where neither has one.
BundledPromptFile? bundledPromptFileOf(
    List<BundledPromptFile> files, String? project, String name) {
  final tags = [
    if (project != null && project != "default") project,
    "default",
  ];
  for (final tag in tags) {
    for (final file in files) {
      if (file.project == tag && file.name == name) return file;
    }
  }
  return null;
}